ruleToc.chapterList:
@js:
var chapters = [];
var domain = (baseUrl.match(/^https?:\/\/[^\/]+/) || [''])[0];
var html = src || result || '';

function toAbs(u) { return u.indexOf('http') < 0 ? domain + (u.indexOf('/') === 0 ? '' : '/') + u : u; }
function grabUl(ulHtml) {
    var out = [];
    var re = /<li><a href="([^"]+)"[^>]*>([\s\S]*?)<\/a><\/li>/g;
    var m;
    while ((m = re.exec(ulHtml))) {
        var name = m[2].replace(/<[^>]+>/g, '').replace(/^\s+|\s+$/g, '');
        if (name && m[1]) out.push({text: name, href: m[1]});
    }
    return out;
}
function selectPages(h) {
    var sel = h.match(/<select[^>]*>([\s\S]*?)<\/select>/);
    var urls = [];
    if (sel) {
        var re = /<option[^>]*value="([^"]+)"/g, om;
        while ((om = re.exec(sel[1]))) { var u = toAbs(om[1]); if (urls.indexOf(u) < 0) urls.push(u); }
    }
    return urls;
}

// 1. 从详情页 章节列表 区块抓取第1-100章(排除最新章节干扰)
var cs = html.match(/<h3[^>]*>章节列表[\s\S]*?<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
if (cs) chapters = chapters.concat(grabUl(cs[1]));

// 2. 找到第一个 index 页
var firstIndex = html.match(/href="([^"]*index_\d+\.html)"/);
var pages = [];
if (firstIndex) {
    var idxHtml = java.ajax(toAbs(firstIndex[1]));
    pages = selectPages(idxHtml);
    var u2 = idxHtml.match(/<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
    if (u2) chapters = chapters.concat(grabUl(u2[1]));
}

// 3. 抓取其余 index 页
for (var i = 0; i < pages.length; i++) {
    if (/index_\d+\.html/.test(pages[i])) {
        if (firstIndex && pages[i] === toAbs(firstIndex[1])) continue;
        var h = java.ajax(pages[i]);
        var u3 = h.match(/<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
        if (u3) chapters = chapters.concat(grabUl(u3[1]));
    }
}

// 4. 按 href 去重(保留首次出现)
var seen = {}; var out = [];
for (var k = 0; k < chapters.length; k++) {
    if (!seen[chapters[k].href]) { seen[chapters[k].href] = true; out.push(chapters[k]); }
}
out;
